#!/usr/bin/env python3
"""
Round 102b (culprits), 28 September 2026. Round 101b must be applied first.

Destruction's Of groups and Of individuals pared down; three of the
insentient's kinds out; Christmas tree farms worldwide; the asteroids round
the flat map, pulling the map back, fading with their bar; plain launch titles;
Eyes warmed sooner with the map resting behind it; a picture for each world;
plantations spreading year by year first under their heading.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''
NOTE = '## Round 102b (28 September)\n\nNeeds round 101b (runs after it by name). Tiles patch round102b_tiles.py beside it.\n\n- Destruction: Of groups keeps Of humans only (Of animals, Of plants, Of\n  microorganisms, Of the insentient gone); Of individuals keeps Of humans and\n  Of animals (Of plants, Of microscopics gone).\n- site_insentient: cfg.dropTypes (sitemapDropTypes) takes out "Bottled &\n  decorative water", "Collectibles & novelty", "Luxury & fast fashion" from its\n  type rows and its places.\n- Christmas trees: xmas_trees (geojsonlive, tiles christmas_trees.py: OSM tags\n  and names in many languages, worldwide, merged with the Real Christmas Tree\n  Locator My Maps file) in place of mymaps_trees (PANEL_REMOVED).\n- esa_risk: drawn round the flat world too (ring from its corners), pullBack on\n  turning on (globe or flat), FREE_FLAT shared by rows (freeFlatFor), and the\n  see-through bar reaches canvas rows (ROW_OPACITY_HOOKS; worlds too).\n- Launches retitled (The Space Devs); pads\' "On a map" link gone.\n- Eyes: warmSpace on pointerenter/focus of Leave Earth and below handoff+2;\n  map hidden and stopped while away (pauseMapWhileAway).\n- biosignature cards: a picture from the Wikipedia article on each world\n  (REST summary; WORLD_ARTICLES for shared names; exoplanets said to be\n  artists\' impressions).\n- CATALOGUE_FIRST also by item.name: Global_AllExpansionRGB_2000to2025 leads\n  Plantations of no single crop.\n- Script version app.js?v=993.\n\n'
HEAD = "## Round 102b (28 September)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round102b: run from the culprits repository root")
    if "## Round 101b" not in (root / "HANDOFF.md").read_text(encoding="utf-8"):
        sys.exit("round102b: round 101b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round102b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round102b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round102b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 101b")
        h.write_text(text[:at] + NOTE + "\n" + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
